<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import {create} from '../api/datasets';import {useAsync} from '../hooks/useAsync';import {PERIODS} from '../constants/enums';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const selected=ref(''),name=ref(''),source=ref('intake_observations.json'),text=ref('');const dataset=computed(()=>props.data.datasets.find(d=>d.id===selected.value)||props.data.datasets[0]);const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await create({name:name.value,source:source.value,rows:JSON.parse(text.value)});name.value='';text.value='';await props.refresh()})};
</script><template><PageHeading code="02 / INTAKE OBSERVATIONS" title="把等候，拆回到达与服务。" description="每条记录保留匿名样本编号、时段、到达间隔与服务时长。单位统一为分钟。"/><section class="paper"><div class="section-heading"><h2>时长观测簿</h2><select aria-label="选择观测集" :value="dataset?.id" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></div><template v-if="dataset"><div class="data-caption"><b>{{dataset.rows.length}}条观测</b><span>{{dataset.source}}</span><span>无真实个人信息</span></div><div class="table-scroll"><table><thead><tr><th>匿名样本</th><th>时段</th><th>到达间隔 / 分钟</th><th>服务时长 / 分钟</th></tr></thead><tbody><tr v-for="r in dataset.rows.slice(0,40)" :key="r.sample_id"><td>{{r.sample_id}}</td><td>{{PERIODS[r.period]}}</td><td>{{r.interarrival_minutes.toFixed(3)}}</td><td>{{r.service_minutes.toFixed(3)}}</td></tr></tbody></table></div><p class="caption">预览前40条，剖面估计使用所选时段的全部观测。</p></template><Notice v-else>请先导入至少20条时长观测，再创建服务剖面。</Notice></section><section v-if="canWrite" class="paper"><h2>导入匿名时长观测</h2><form class="grid-form" @submit.prevent="submit"><label>观测集名称<input required minlength="2" v-model="name"/></label><label>来源文件名<input v-model="source"/></label><label class="wide">JSON数组<textarea rows="4" required v-model="text" placeholder='[{"sample_id":"YX-01","period":"peak","interarrival_minutes":4,"service_minutes":12}, …]'/></label><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">核查并导入</button></form></section></template>
